<?php
declare(strict_types=1);
require_once __DIR__.'/web_common.php';
function cp_merchant_products(PDO $pdo):array{$rows=$pdo->query("SELECT p.id,p.name,p.sku,p.description,p.sale_price,p.pricing_type,(SELECT i.path FROM cp_product_images i WHERE i.product_id=p.id AND i.enabled=1 ORDER BY i.sort_order,i.id LIMIT 1) image_path,inv.stock_mode,inv.quantity,inv.reserved_quantity FROM cp_products p LEFT JOIN cp_product_inventory inv ON inv.product_id=p.id WHERE p.enabled=1 AND p.visible_web=1 AND p.pricing_type='fixed' AND p.sale_price IS NOT NULL ORDER BY p.id")->fetchAll(PDO::FETCH_ASSOC);$brand=cp_web_company()['trade_name']?:cp_web_company()['legal_name'];foreach($rows as &$r){$available=$r['stock_mode']===null||$r['stock_mode']==='unlimited'?null:max(0,(float)$r['quantity']-(float)$r['reserved_quantity']);$r['availability']=$available===null||$available>0?'in_stock':'out_of_stock';$r['image_url']=cp_web_image($r['image_path']??'');$r['url']=cp_web_absolute('/producto.php',['id'=>(int)$r['id']]);$r['description']=cp_web_sanitize_text((string)($r['description']??$r['name']),5000);$r['brand']=$brand;$r['identifier_exists']='no';}unset($r);return$rows;}
